/**
 * What: Emits node:test files (CAP cds.test, in-process) from the test plan: one file per entity
 *     set plus one for unbound operations, each with a What/Why/If-missing header and a
 *     "generated - do not edit" note.
 * Why: CAP teams get runnable regression tests (CRUD, validation, draft, ETag, authorization)
 *     without writing boilerplate; hand-written business scenarios stay in test/scenarios/.
 * If missing or unlinked: odata-testgen cannot produce node:test output for CAP projects.
 */

/**
 * @typedef {import('./plan.js').ServicePlan} ServicePlan
 * @typedef {import('./plan.js').EntityPlan} EntityPlan
 * @typedef {import('./plan.js').OperationPlan} OperationPlan
 * @typedef {import('./access.js').User} User
 */

const json = (/** @type {unknown} */ v) => JSON.stringify(v);
const userRef = (/** @type {User} */ u) => `{ username: ${json(u.name)}, password: ${json(u.password)} }`;

/**
 * @param {ServicePlan[]} plans
 * @param {{ projectRoot: string, command: string }} options
 *   projectRoot: path from the output folder to the CAP project root (e.g. "../..")
 * @returns {Array<{ path: string, content: string }>}
 */
export function emitNodeTests(plans, { projectRoot, command }) {
  /** @type {Array<{ path: string, content: string }>} */
  const files = [];
  for (const plan of plans) {
    for (const e of plan.entities) files.push({ path: `${plan.service}.${e.set.name}.test.js`, content: entityFile(e, projectRoot, command) });
    if (plan.unbound.length) files.push({ path: `${plan.service}.operations.test.js`, content: operationsFile(plan, projectRoot, command) });
  }
  return files;
}

/**
 * @param {string} subject
 * @param {string} command
 */
function header(subject, command) {
  return `/**
 * What: GENERATED by odata-testgen - regression tests for ${subject}: reads, query options,
 *     create/update/delete, validation, draft, ETag and authorization as far as the API allows.
 * Why: Baseline API coverage without hand-written boilerplate; complex business scenarios belong
 *     in hand-written tests under test/scenarios/.
 * If missing or unlinked: The API loses its generated regression coverage; regenerate with
 *     \`${command}\`. Do not edit this file - changes are overwritten on regeneration.
 */`;
}

/**
 * Shared runtime helpers emitted into every file (no dependency on odata-testgen at test time).
 * @param {string} projectRoot
 */
function prelude(projectRoot) {
  return `import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import cds from '@sap/cds';

const { GET, POST, PATCH, DELETE } = cds.test(\`\${import.meta.dirname}/${projectRoot}\`);

/** Response of a request, also for 4xx/5xx (cds.test throws on error statuses). */
async function send(request) {
  try {
    return await request;
  } catch (err) {
    if (err.response) return err.response;
    if (err.status) return { status: err.status, data: err.data, headers: {} };
    throw err;
  }
}

const as = (user, extra = {}) => (user ? { ...extra, auth: user } : extra);`;
}

/**
 * @param {EntityPlan} e
 * @param {string} projectRoot
 * @param {string} command
 */
function entityFile(e, projectRoot, command) {
  const { set } = e;
  const draft = set.draft;
  const keyTypes = Object.fromEntries(set.keys.map((k) => [k, set.properties.find((p) => p.name === k)?.type ?? 'Edm.String']));
  const generatedKeys = set.keys.filter((k) => !set.properties.find((p) => p.name === k)?.computed);
  const users = { reader: e.reader, writer: e.writer, deniedReader: e.deniedReader, deniedWriter: e.deniedWriter };
  /** @type {string[]} */
  const tests = [];
  const caps = set.capabilities;
  const canCreate = caps.insertable && e.writer;

  if (e.anonymousDenied) {
    tests.push(`  it('rejects anonymous access with 401', async () => {
    assert.equal((await send(GET(BASE))).status, 401);
  });`);
  }
  if (caps.readable && e.reader) {
    tests.push(`  it('reads the collection with $top and $count as ${e.reader.name}', async () => {
    const res = await send(GET(\`\${BASE}?$top=2&$count=true\`, as(users.reader)));
    assert.equal(res.status, 200);
    assert.ok(Array.isArray(res.data.value));
  });`);
    if (e.stringProperty) {
      tests.push(`  it('supports $filter and $orderby on ${e.stringProperty.name}', async () => {
    const res = await send(GET(\`\${BASE}?$filter=${e.stringProperty.name} eq 'no-such-value'&$orderby=${e.stringProperty.name} desc\`, as(users.reader)));
    assert.equal(res.status, 200);
    assert.deepEqual(res.data.value, []);
  });`);
    }
  }
  if (caps.readable && e.deniedReader) {
    tests.push(`  it('forbids read for ${e.deniedReader.name} with 403', async () => {
    assert.equal((await send(GET(BASE, as(users.deniedReader)))).status, 403);
  });`);
  }
  if (canCreate) {
    tests.push(`  it('creates an entity and reads it back', async () => {
    const created = await create();
    if (${caps.readable && e.reader ? 'true' : 'false'}) {
      const res = await send(GET(BASE + key(created, ${draft ? 'true' : 'undefined'}), as(users.reader)));
      assert.equal(res.status, 200);
    }
  });`);
    if (e.mandatory.length) {
      tests.push(draft
        ? `  it('rejects activation with missing mandatory fields (${e.mandatory.join(', ')}) with 400', async () => {
    const res = await send(POST(BASE, withoutMandatory(), as(users.writer)));
    assert.equal(res.status, 201, 'draft creation accepts incomplete data');
    const activation = await send(POST(\`\${BASE}\${key(res.data, false)}/\${SERVICE}.draftActivate\`, {}, as(users.writer)));
    assert.equal(activation.status, 400);
  });`
        : `  it('rejects missing mandatory fields (${e.mandatory.join(', ')}) with 400', async () => {
    assert.equal((await send(POST(BASE, withoutMandatory(), as(users.writer)))).status, 400);
  });`);
    }
    if (e.typedProperty) {
      tests.push(`  it('rejects an invalid ${e.typedProperty.type} value for ${e.typedProperty.name} with 400', async () => {
    const res = await send(POST(BASE, { ...newPayload(), ${json(e.typedProperty.name)}: 'not-a-valid-value' }, as(users.writer)));
    assert.equal(res.status, 400);
  });`);
    }
  }
  if (caps.insertable && e.deniedWriter) {
    tests.push(`  it('forbids create for ${e.deniedWriter.name} with 403', async () => {
    assert.equal((await send(POST(BASE, newPayload(), as(users.deniedWriter)))).status, 403);
  });`);
  }
  if (canCreate && caps.updatable && e.stringProperty) {
    const prop = json(e.stringProperty.name);
    tests.push(draft
      ? `  it('edits through the draft protocol (edit, change, activate)', async () => {
    const created = await create();
    const edit = await send(POST(\`\${BASE}\${key(created, true)}/\${SERVICE}.draftEdit\`, { PreserveChanges: true }, as(users.writer)));
    assert.ok([200, 201].includes(edit.status), \`draftEdit returned \${edit.status}\`);
    assert.equal((await send(PATCH(BASE + key(created, false), { ${prop}: 'U' }, as(users.writer)))).status, 200);
    const activation = await send(POST(\`\${BASE}\${key(created, false)}/\${SERVICE}.draftActivate\`, {}, as(users.writer)));
    assert.ok([200, 201].includes(activation.status), \`draftActivate returned \${activation.status}\`);
  });`
      : `  it('updates an entity', async () => {
    const created = await create();
    assert.equal((await send(PATCH(BASE + key(created), { ${prop}: 'U' }, as(users.writer, ifMatch(created))))).status, 200);
  });`);
  }
  if (canCreate && caps.deletable) {
    tests.push(`  it('deletes an entity', async () => {
    const created = await create();
    assert.equal((await send(DELETE(BASE + key(created, ${draft ? 'true' : 'undefined'}), as(users.writer, ${draft ? '{}' : 'ifMatch(created)'})))).status, 204);
  });`);
  }
  if (canCreate && set.etag && !draft && caps.updatable && e.stringProperty) {
    tests.push(`  it('rejects an update with a stale ETag with 412', async () => {
    const created = await create();
    const res = await send(PATCH(BASE + key(created), { ${json(e.stringProperty.name)}: 'U' }, as(users.writer, { headers: { 'If-Match': 'W/"stale"' } })));
    assert.equal(res.status, 412);
  });`);
  }
  for (const op of e.boundOperations) tests.push(...operationTests(op, { bound: true, canCreate: Boolean(canCreate), draft }));

  return `${header(`${e.service}.${set.name}`, command)}
${prelude(projectRoot)}

const SERVICE = ${json(e.service)};
const BASE = ${json(`${e.basePath}/${set.name}`)};
const users = {
${Object.entries(users)
  .filter(([, u]) => u)
  .map(([role, u]) => `  ${role}: ${userRef(/** @type {User} */ (u))},`)
  .join('\n')}
};
const PAYLOAD = ${json(e.payload)};
const MANDATORY = ${json(e.mandatory)};
const KEY_TYPES = ${json(keyTypes)};
const GENERATED_KEYS = ${json(generatedKeys)};
let sequence = 0;

/** Payload with fresh values for client-provided keys. */
function newPayload() {
  sequence += 1;
  const data = { ...PAYLOAD };
  for (const k of GENERATED_KEYS) {
    const type = KEY_TYPES[k];
    data[k] = type === 'Edm.Guid' ? cds.utils.uuid() : type.startsWith('Edm.Int') ? Date.now() % 100000 + sequence : \`K\${sequence}\${Date.now() % 10000}\`;
  }
  return data;
}

function withoutMandatory() {
  const data = newPayload();
  for (const m of MANDATORY) delete data[m];
  return data;
}

/** OData key predicate; active=true/false adds IsActiveEntity for draft-enabled entities. */
function key(entity, active) {
  const keys = Object.keys(KEY_TYPES);
  const parts = keys.map((k) => {
    const v = KEY_TYPES[k] === 'Edm.String' ? \`'\${String(entity[k]).replace(/'/g, "''")}'\` : String(entity[k]);
    return keys.length === 1 && active === undefined ? v : \`\${k}=\${v}\`;
  });
  if (active !== undefined) parts.push(\`IsActiveEntity=\${active}\`);
  return \`(\${parts.join(',')})\`;
}

/** If-Match header with the entity's current ETag (CAP rejects writes without it: 428). */
function ifMatch(entity) {
  return ${set.etag && !draft ? "{ headers: { 'If-Match': entity['@odata.etag'] } }" : '{}'};
}

/** Creates an entity${draft ? ' (draft, then activation)' : ''} and returns it. */
async function create() {
  const data = newPayload();
  const res = await send(POST(BASE, data, as(users.writer)));
  // 204 when the caller may create but not read the result (e.g. insert-only entities).
  assert.ok(${caps.readable ? '[201]' : '[201, 204]'}.includes(res.status), \`create returned \${res.status}: \${JSON.stringify(res.data)}\`);${
    draft
      ? `
  const activation = await send(POST(\`\${BASE}\${key(res.data, false)}/\${SERVICE}.draftActivate\`, {}, as(users.writer)));
  assert.ok([200, 201].includes(activation.status), \`draftActivate returned \${activation.status}: \${JSON.stringify(activation.data)}\`);
  return activation.data;`
      : `
  return res.status === 204 ? data : res.data;`
  }
}

describe(${json(`${e.service}.${set.name} (generated)`)}, () => {
${tests.join('\n\n')}
});
`;
}

/**
 * Smoke and authorization tests for one operation.
 * @param {OperationPlan} p
 * @param {{ bound: boolean, canCreate: boolean, draft?: boolean }} ctx
 */
function operationTests(p, { bound, canCreate, draft }) {
  const { op } = p;
  if (bound && !canCreate) return [];
  /** @type {string[]} */
  const tests = [];
  const target = bound
    ? `\`\${BASE}\${key(await create(), ${draft ? 'true' : 'undefined'})}/\${SERVICE}.${op.name}\``
    : json(`/${op.name}`);
  const call = (/** @type {string} */ user) =>
    op.kind === 'function'
      ? `GET(${bound ? `${target} + ${json(fnArgs(p.params))}` : `BASE + ${json(`/${op.name}${fnArgs(p.params)}`)}`}, as(${user}))`
      : `POST(${bound ? target : `BASE + ${target}`}, ${json(p.params)}, as(${user}))`;
  if (p.allowedUser) {
    tests.push(`  it('${op.kind} ${op.name} is reachable for ${p.allowedUser.name} (smoke)', async () => {
    const res = await send(${call(userRef(p.allowedUser))});
    assert.ok(res.status < 500 && ![401, 403, 404, 405].includes(res.status), \`unexpected status \${res.status}: \${JSON.stringify(res.data)}\`);
  });`);
  }
  if (p.deniedUser) {
    tests.push(`  it('${op.kind} ${op.name} is forbidden for ${p.deniedUser.name} with 403', async () => {
    assert.equal((await send(${call(userRef(p.deniedUser))})).status, 403);
  });`);
  }
  if (p.anonymousDenied && !bound) {
    tests.push(`  it('${op.kind} ${op.name} rejects anonymous calls with 401', async () => {
    assert.equal((await send(${call('undefined')})).status, 401);
  });`);
  }
  return tests;
}

/** @param {Record<string, unknown>} params */
function fnArgs(params) {
  const args = Object.entries(params).map(([k, v]) => `${k}=${typeof v === 'string' ? `'${v}'` : v}`);
  return `(${args.join(',')})`;
}

/**
 * @param {ServicePlan} plan
 * @param {string} projectRoot
 * @param {string} command
 */
function operationsFile(plan, projectRoot, command) {
  return `${header(`unbound operations of ${plan.service}`, command)}
${prelude(projectRoot)}

const BASE = ${json(plan.basePath)};

describe(${json(`${plan.service} operations (generated)`)}, () => {
${plan.unbound.flatMap((p) => operationTests(p, { bound: false, canCreate: false })).join('\n\n')}
});
`;
}
